&lt;/td&gt;
    &lt;/tr&gt;
    &lt;tr&gt;&lt;td&gt;&lt;b&gt;Inquisitions&lt;/b&gt;&lt;/td&gt;
        &lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Inquisitions.html#FERVEUR&quot; title=&quot;Les inquisitions d&amp;#39;inquisiteur&quot;&gt;Ferveur&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Inquisitions.html#HEROISME&quot; title=&quot;Les inquisitions d&amp;#39;inquisiteur&quot;&gt;H&#233;ro&#239;sme&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Inquisitions.html#SEDITION&quot; title=&quot;Les inquisitions d&amp;#39;inquisiteur&quot;&gt;S&#233;dition&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Inquisitions.html#SEDUCTION&quot; title=&quot;Les inquisitions d&amp;#39;inquisiteur&quot;&gt;S&#233;duction&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Inquisitions.html#VRAIEMORT&quot; title=&quot;Les inquisitions d&amp;#39;inquisiteur&quot;&gt;Vraie mort&lt;/a&gt;&lt;/td&gt;
    &lt;/tr&gt;
